// expandSaasRuntimeFlagVariants expands `variants` (`Flag.FlagVariant`) by
// dispatching on `flag_value_type` so only the matching `FlagVariant.value`
// protobuf `oneof` branch is emitted (including explicit zero values such as
// `boolean_value = false`, `integer_value = 0`, `double_value = 0.0`, or
// `string_value = ""`).
func expandSaasRuntimeFlagVariants(v interface{}, d tpgresource.TerraformResourceData, config *transport_tpg.Config) (interface{}, error) {
	if v == nil {
		return nil, nil
	}
	l, ok := v.([]interface{})
	if !ok {
		return nil, nil
	}
	var fvt string
	if d != nil {
		fvt, _ = d.Get("flag_value_type").(string)
	}
	req := make([]interface{}, 0, len(l))
	for _, raw := range l {
		if raw == nil {
			continue
		}
		original, ok := raw.(map[string]interface{})
		if !ok {
			continue
		}
		transformed := make(map[string]interface{})

		if id, ok := original["id"].(string); ok && id != "" {
			transformed["id"] = id
		}
		if desc, ok := original["description"].(string); ok && desc != "" {
			transformed["description"] = desc
		}

		switch fvt {
		case "FLAG_VALUE_TYPE_BOOLEAN":
			if bv, ok := original["boolean_value"].(bool); ok {
				transformed["booleanValue"] = bv
			}
		case "FLAG_VALUE_TYPE_INTEGER":
			if iv, ok := original["integer_value"].(int); ok {
				transformed["integerValue"] = iv
			}
		case "FLAG_VALUE_TYPE_STRING":
			if sv, ok := original["string_value"].(string); ok {
				transformed["stringValue"] = sv
			}
		case "FLAG_VALUE_TYPE_DOUBLE":
			if dv, ok := original["double_value"].(float64); ok {
				transformed["doubleValue"] = dv
			}
		}

		req = append(req, transformed)
	}
	return req, nil
}

